mapper.select:
SELECT d.dept_id AS deptId, d.dept_name AS deptName,
ds.doctor_id AS doctorId, (SELECT doctor_name FROM doctor WHERE doctor_id = ds.doctor_id LIMIT 1) AS doctorName,
NULL AS doctorId, NULL AS doctorName,
NULL AS visitDurationHours, NULL AS totalQuota, NULL AS usedQuota, COUNT(rr.record_id) AS quotaUsageRate FROM doctor_schedule ds INNER JOIN department d ON ds.dept_id = d.dept_id LEFT JOIN registration_record rr ON rr.schedule_id = ds.schedule_id AND rr.status IN (0, 1, 2)
AND DATE(rr.register_time) >= #{startDate}
AND DATE(rr.register_time) <= #{endDate}
WHERE ds.status = 1
AND ds.schedule_date >= #{startDate}
AND ds.schedule_date <= #{endDate}
AND (ds.dept_id = #{deptId} OR d.parent_dept_id = #{deptId})
AND ds.doctor_id = #{doctorId}
GROUP BY d.dept_id, d.dept_name
, ds.doctor_id
ORDER BY d.dept_id

SELECT d.dept_id AS deptId, d.dept_name AS deptName, NULL AS doctorId, NULL AS doctorName, NULL AS typeId, NULL AS typeName, COUNT(*) AS totalRegistration, SUM( CASE WHEN rr.status IN (3, 4) OR rr.cancel_time IS NOT NULL THEN 1 ELSE 0 END ) AS cancelCount, CASE WHEN COUNT(*) > 0 THEN CAST(ROUND( SUM(CASE WHEN rr.status IN (3, 4) OR rr.cancel_time IS NOT NULL THEN 1 ELSE 0 END) * 100.0 / COUNT(*), 2 ) AS DECIMAL(10, 2)) ELSE CAST(0 AS DECIMAL(10, 2)) END AS cancelRate FROM registration_record rr INNER JOIN doctor_schedule ds ON rr.schedule_id = ds.schedule_id INNER JOIN department d ON ds.dept_id = d.dept_id WHERE 1 = 1
AND DATE(rr.register_time) >= #{startDate}
AND DATE(rr.register_time) <= #{endDate}
AND (ds.dept_id = #{deptId} OR d.parent_dept_id = #{deptId})
GROUP BY d.dept_id, d.dept_name ORDER BY cancelRate DESC

SELECT d.dept_id AS deptId, d.dept_name AS deptName, doc.doctor_id AS doctorId, doc.doctor_name AS doctorName, NULL AS typeId, NULL AS typeName, COUNT(*) AS totalRegistration, SUM( CASE WHEN rr.status IN (3, 4) OR rr.cancel_time IS NOT NULL THEN 1 ELSE 0 END ) AS cancelCount, CASE WHEN COUNT(*) > 0 THEN CAST(ROUND( SUM(CASE WHEN rr.status IN (3, 4) OR rr.cancel_time IS NOT NULL THEN 1 ELSE 0 END) * 100.0 / COUNT(*), 2 ) AS DECIMAL(10, 2)) ELSE CAST(0 AS DECIMAL(10, 2)) END AS cancelRate FROM registration_record rr INNER JOIN doctor_schedule ds ON rr.schedule_id = ds.schedule_id INNER JOIN department d ON ds.dept_id = d.dept_id INNER JOIN doctor doc ON rr.doctor_id = doc.doctor_id WHERE 1 = 1
AND DATE(rr.register_time) >= #{startDate}
AND DATE(rr.register_time) <= #{endDate}
AND rr.doctor_id = #{doctorId}
GROUP BY d.dept_id, d.dept_name, doc.doctor_id, doc.doctor_name ORDER BY cancelRate DESC

SELECT NULL AS deptId, NULL AS deptName, NULL AS doctorId, NULL AS doctorName, rt.type_id AS typeId, rt.type_name AS typeName, COUNT(*) AS totalRegistration, SUM( CASE WHEN rr.status IN (3, 4) OR rr.cancel_time IS NOT NULL THEN 1 ELSE 0 END ) AS cancelCount, CASE WHEN COUNT(*) > 0 THEN CAST(ROUND( SUM(CASE WHEN rr.status IN (3, 4) OR rr.cancel_time IS NOT NULL THEN 1 ELSE 0 END) * 100.0 / COUNT(*), 2 ) AS DECIMAL(10, 2)) ELSE CAST(0 AS DECIMAL(10, 2)) END AS cancelRate FROM registration_record rr INNER JOIN registration_type rt ON rr.type_id = rt.type_id WHERE 1 = 1
AND DATE(rr.register_time) >= #{startDate}
AND DATE(rr.register_time) <= #{endDate}
AND rr.type_id = #{typeId}
GROUP BY rt.type_id, rt.type_name ORDER BY cancelRate DESC

SELECT COALESCE(SUM(rr.actual_price), 0) AS totalIncome
FROM registration_record rr
    INNER JOIN doctor_schedule ds ON rr.schedule_id = ds.schedule_id
    INNER JOIN department d ON ds.dept_id = d.dept_id
WHERE rr.status IN (1, 2)  -- 已预约或已就诊

        AND DATE(rr.register_time) >= #{startDate}


        AND DATE(rr.register_time) <= #{endDate}


        AND (ds.dept_id = #{deptId} OR d.parent_dept_id = #{deptId})


        AND rr.doctor_id = #{doctorId}

SELECT COUNT(*) AS cnt FROM registration_record rr INNER JOIN doctor_schedule ds ON rr.schedule_id = ds.schedule_id INNER JOIN department d ON ds.dept_id = d.dept_id WHERE rr.status IN (1, 2)
AND DATE(rr.register_time) >= #{startDate}
AND DATE(rr.register_time) <= #{endDate}
AND (ds.dept_id = #{deptId} OR d.parent_dept_id = #{deptId})

SELECT COUNT(DISTINCT ds.doctor_id) AS cnt FROM doctor_schedule ds INNER JOIN department d ON ds.dept_id = d.dept_id WHERE ds.status = 1
AND ds.schedule_date >= #{startDate}
AND ds.schedule_date <= #{endDate}
AND (ds.dept_id = #{deptId} OR d.parent_dept_id = #{deptId})

SELECT ds.time_slot AS timeSlot, COUNT(*) AS cnt FROM registration_record rr INNER JOIN doctor_schedule ds ON rr.schedule_id = ds.schedule_id WHERE rr.status IN (1, 2)
AND DATE(rr.register_time) >= #{startDate}
AND DATE(rr.register_time) <= #{endDate}
GROUP BY ds.time_slot ORDER BY ds.time_slot

SELECT d.dept_id AS deptId, d.dept_name AS deptName, SUM(CASE WHEN rr.status IN (1, 2) THEN 1 ELSE 0 END) AS registerCount, SUM(CASE WHEN rr.status IN (3, 4) THEN 1 ELSE 0 END) AS cancelCount, SUM(CASE WHEN rr.status IN (1, 2) THEN rr.actual_price ELSE 0 END) AS income FROM registration_record rr INNER JOIN doctor_schedule ds ON rr.schedule_id = ds.schedule_id INNER JOIN department d ON ds.dept_id = d.dept_id WHERE 1 = 1
AND DATE(rr.register_time) >= #{startDate}
AND DATE(rr.register_time) <= #{endDate}
GROUP BY d.dept_id, d.dept_name ORDER BY income DESC

SELECT doc.doctor_id AS doctorId, COALESCE(doc.doctor_name, '未知医生') AS doctorName, d.dept_id AS deptId, d.dept_name AS deptName, SUM(CASE WHEN rr.status IN (1, 2) THEN 1 ELSE 0 END) AS registerCount, SUM(CASE WHEN rr.status IN (3, 4) THEN 1 ELSE 0 END) AS cancelCount, SUM(CASE WHEN rr.status IN (1, 2) THEN rr.actual_price ELSE 0 END) AS income FROM registration_record rr INNER JOIN doctor_schedule ds ON rr.schedule_id = ds.schedule_id INNER JOIN department d ON ds.dept_id = d.dept_id LEFT JOIN doctor doc ON rr.doctor_id = doc.doctor_id WHERE 1 = 1
AND DATE(rr.register_time) >= #{startDate}
AND DATE(rr.register_time) <= #{endDate}
GROUP BY doc.doctor_id, doc.doctor_name, d.dept_id, d.dept_name ORDER BY income DESC

SELECT rr.patient_id AS patientId, p.student_id AS studentId, p.staff_id AS staffId, COALESCE(p.patient_name, '') AS patientName, p.gender AS gender, d.dept_name AS deptName, rr.register_time AS registerTime FROM registration_record rr INNER JOIN doctor_schedule ds ON rr.schedule_id = ds.schedule_id INNER JOIN department d ON ds.dept_id = d.dept_id LEFT JOIN patient p ON rr.patient_id = p.patient_id WHERE rr.status IN (1, 2)
AND DATE(rr.register_time) >= #{startDate}
AND DATE(rr.register_time) <= #{endDate}
ORDER BY rr.register_time DESC LIMIT 5
